<?php
$period=$view==='month'?'month':($view==='week'?'week':($view==='day'?'day':'month'));
$previous=(new DateTimeImmutable($date))->modify('-1 '.$period)->format('Y-m-d');
$next=(new DateTimeImmutable($date))->modify('+1 '.$period)->format('Y-m-d');
$link=static fn(string $mode,string $day): string => '/uni/calendar/subscription?view='.rawurlencode($mode).'&date='.rawurlencode($day);
$today=date('Y-m-d');
?>
<header class="page-header"><div><h1><?= e(t('University calendar')) ?></h1><p class="muted"><?= e(t('Your subscribed lectures, saved for offline viewing.')) ?></p></div><a href="/uni/calendar"><?= e(t('NIBM calendar')) ?></a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<?php if ($changes): $items=json_decode($changes['changes_json'] ?? '[]',true); ?>
<section class="card" id="lecture-changes"><h2><?= e(t('Calendar changes')) ?></h2><p class="muted"><?= e($changes['body']) ?></p>
<?php if (is_array($items) && $items): ?><ul><?php foreach ($items as $item): if (!is_array($item)) continue; ?><li><strong><?= e(t(ucfirst((string)($item['type'] ?? 'changed')))) ?>:</strong> <a href="/uni/calendar/subscription?view=day&amp;date=<?= e(substr((string)($item['starts_at'] ?? $date),0,10)) ?>&amp;event=<?= e((string)($item['appointment_id'] ?? '')) ?>#lecture-detail"><?= e((string)($item['title'] ?? '')) ?></a></li><?php endforeach; ?></ul><?php endif; ?>
</section><?php endif; ?>
<section class="card uni-subscription" id="calendar-connection"><div class="section-heading"><h2><?= e(t('Calendar connection')) ?></h2><span class="badge"><?= e(t($status['connected']?'Connected':'Not connected')) ?></span></div>
<?php if ($status['connected']): ?>
<p><?= e(t('Connected calendar host')) ?>: <strong><?= e($status['host']) ?></strong></p>
<p class="muted"><?= e(t('Last successful sync')) ?>: <?= e($status['lastSync'] ?: t('Waiting for first sync')) ?></p>
<?php if ($status['feedFirst'] && $status['feedLast']): ?><p class="muted"><?= e(t('Dates currently supplied by this feed')) ?>: <?= e($status['feedFirst']) ?> – <?= e($status['feedLast']) ?></p><?php endif; ?>
<?php if ($status['lastError']): ?><p class="error-text" role="alert"><?= e(t($status['lastError'])) ?></p><?php endif; ?>
<div class="hero-actions"><form method="post" action="/uni/calendar/subscription/sync"><?= csrf_field() ?><button><?= e(t('Sync now')) ?></button></form>
<form method="post" action="/uni/calendar/subscription/disconnect" data-confirm="Disconnect this calendar? Saved lectures will remain available offline."><?= csrf_field() ?><button class="secondary"><?= e(t('Disconnect calendar')) ?></button></form></div>
<form method="post" action="/uni/calendar/subscription/automatic" class="stack"><?= csrf_field() ?><label class="checkbox-label"><input type="checkbox" name="enabled" value="1" <?= $status['automatic']?'checked':'' ?>><span><?= e(t('Sync automatically while LifeOS is open')) ?></span></label><button class="secondary"><?= e(t('Save preference')) ?></button></form>
<details><summary><?= e(t('Change calendar URL')) ?></summary><form method="post" action="/uni/calendar/subscription/connect" class="stack"><?= csrf_field() ?><label><?= e(t('Private ICS calendar URL')) ?><input type="url" name="calendar_url" maxlength="2048" placeholder="https://example.edu/calendar.ics" required autocomplete="off"></label><button><?= e(t('Connect calendar')) ?></button></form></details>
<?php else: ?><p class="muted"><?= e(t('Paste your private ICS subscription link. LifeOS will check the feed and remember it for this profile.')) ?></p><form method="post" action="/uni/calendar/subscription/connect" class="stack"><?= csrf_field() ?><label><?= e(t('Private ICS calendar URL')) ?><input type="url" name="calendar_url" maxlength="2048" placeholder="https://example.edu/calendar.ics" required autocomplete="off"></label><button><?= e(t('Connect calendar')) ?></button></form><?php endif; ?>
<p class="footnote"><?= e(t('Automatic sync runs only while LifeOS is open. Previously synchronized lectures remain visible when offline.')) ?></p></section>
<section class="card uni-subscription" id="lecture-schedule"><div class="section-heading"><div><h2><?= e(t('Lecture schedule')) ?></h2><p class="muted"><?= e($from->format('d M Y')) ?> – <?= e($until->format('d M Y')) ?> · <?= count($events) ?> <?= e(t(count($events)===1?'lecture':'lectures')) ?></p></div><a class="btn secondary" href="<?= e($link('day',$today)) ?>"><?= e(t('Today')) ?></a></div>
<nav class="uni-calendar-modes" aria-label="<?= e(t('Calendar views')) ?>"><?php foreach (['month'=>'Month','week'=>'Week','day'=>'Day','agenda'=>'Agenda'] as $mode=>$label): ?><a href="<?= e($link($mode,$date)) ?>" <?= $view===$mode?'aria-current="page"':'' ?>><?= e(t($label)) ?></a><?php endforeach; ?></nav>
<div class="uni-calendar-navigation"><a href="<?= e($link($view,$previous)) ?>" aria-label="<?= e(t('Previous')) ?>">←</a><strong><?= e($from->format($view==='month'?'F Y':'d M Y')) ?></strong><a href="<?= e($link($view,$next)) ?>" aria-label="<?= e(t('Next')) ?>">→</a></div>
<form method="get" action="/uni/calendar/subscription" class="uni-calendar-filter"><input type="hidden" name="view" value="<?= e($view) ?>"><label><?= e(t('Date')) ?><input type="date" name="date" value="<?= e($date) ?>"></label><label><?= e(t('Search lectures')) ?><input type="search" name="q" value="<?= e($search) ?>" maxlength="100"></label><label><?= e(t('Module')) ?><select name="module"><option value=""><?= e(t('All modules')) ?></option><?php foreach (array_unique(array_column($events,'title')) as $title): ?><option value="<?= e($title) ?>" <?= $module===$title?'selected':'' ?>><?= e($title) ?></option><?php endforeach; ?></select></label><button class="secondary"><?= e(t('Filter')) ?></button></form>
<?php if (!$events): ?><p class="empty muted"><?= e(t('No lectures in this view.')) ?></p><?php elseif ($view==='month'):
    $first=$from->modify('monday this week'); $last=$until->modify('sunday this week');
    $byDay=[]; foreach ($events as $event) $byDay[substr($event['starts_at'],0,10)][]=$event;
?><div class="uni-calendar-grid" role="grid" aria-label="<?= e(t('Month')) ?>">
<?php foreach (['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $weekday): ?><span class="uni-calendar-weekday"><?= e($weekday) ?></span><?php endforeach; ?>
<?php for ($day=$first;$day<=$last;$day=$day->modify('+1 day')): $key=$day->format('Y-m-d'); ?><div class="uni-calendar-cell <?= $day->format('m')===$from->format('m')?'':'is-outside' ?> <?= $key===$today?'is-today':'' ?>"><strong><?= e($day->format('j')) ?></strong><?php foreach (array_slice($byDay[$key] ?? [],0,4) as $event): ?><a href="<?= e($link('day',$key).'&event='.$event['id']) ?>"><?= e(substr($event['starts_at'],11,5)) ?> <?= e($event['title']) ?></a><?php endforeach; ?><?php if (count($byDay[$key] ?? [])>4): ?><a href="<?= e($link('day',$key)) ?>"><?= e(t('View all')) ?></a><?php endif; ?></div><?php endfor; ?></div>
<?php else: ?><div class="lecture-agenda"><?php $lastDay=''; foreach ($events as $event): $day=substr($event['starts_at'],0,10); if ($day!==$lastDay): $lastDay=$day; ?><h3 class="lecture-day"><?= e((new DateTimeImmutable($day))->format('D, d M Y')) ?></h3><?php endif; ?><a class="lecture-session <?= $event['status']==='cancelled'?'is-cancelled':'' ?>" href="<?= e($link($view,$date).'&event='.$event['id']) ?>"><time><?= e(substr($event['starts_at'],11,5)) ?> – <?= e(substr($event['ends_at'],11,5)) ?></time><strong><?= e($event['title']) ?></strong><span><?= e($event['location']) ?></span></a><?php endforeach; ?></div><?php endif; ?>
<?php if ($lecture): ?><aside class="uni-lecture-detail card" id="lecture-detail"><h3><?= e($lecture['title']) ?></h3><dl class="summary-list"><dt><?= e(t('Start')) ?></dt><dd><?= e($lecture['starts_at']) ?></dd><dt><?= e(t('End')) ?></dt><dd><?= e($lecture['ends_at']) ?></dd><dt><?= e(t('Venue')) ?></dt><dd><?= e($lecture['location'] ?: t('Not provided')) ?></dd><dt><?= e(t('Status')) ?></dt><dd><?= e(t(ucfirst($lecture['status']))) ?></dd></dl><?php if ($lecture['notes']): ?><p><?= nl2br(e($lecture['notes'])) ?></p><?php endif; ?><a href="<?= e($link($view,$date)) ?>"><?= e(t('Close details')) ?></a></aside><?php endif; ?>
</section>
